styles:
:root{
  --ink:#12332C;
  --ink-soft:#274A42;
  --paper:#FCFBF8;
  --tone:#F1EFE8;
  --rule:#DAD5C9;
  --seal:#96692A;
  --verified:#2F6E52;
  --muted:#59635D;
  --display:"Newsreader",Georgia,serif;
  --body:"IBM Plex Sans",system-ui,sans-serif;
  --data:"IBM Plex Mono",ui-monospace,monospace;
  --wrap:1120px;
  --rail:132px;
  --gap:clamp(56px,7vw,104px);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;background:var(--paper);color:var(--ink);
  font-family:var(--body);font-size:17px;line-height:1.65;
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%;display:block}
a{color:inherit}

/* ---------- shell ---------- */
.wrap{max-width:var(--wrap);margin-inline:auto;padding-inline:24px}
.band{padding-block:var(--gap)}
.band--tone{background:var(--tone)}
.band--ink{background:var(--ink);color:#EEF2EF}
.band + .band--tone{border-block-start:1px solid var(--rule)}

/* margin-rail: eyebrow label sits in the document margin */
.rail{display:grid;grid-template-columns:var(--rail) minmax(0,1fr);gap:0 40px}
.rail__label{
  font-family:var(--data);font-size:11px;letter-spacing:.16em;text-transform:uppercase;
  color:var(--muted);padding-block-start:.7em;
  border-inline-start:2px solid var(--seal);padding-inline-start:12px;
}
.band--ink .rail__label{color:#9DB3AB;border-color:#7E9A8F}
@media(max-width:860px){
  .rail{grid-template-columns:1fr;gap:18px}
  .rail__label{padding-block-start:0}
}

/* ---------- type ---------- */
h1,h2,h3{font-family:var(--display);font-weight:400;letter-spacing:-.015em;margin:0}
h1{font-size:clamp(38px,5.6vw,66px);line-height:1.06}
h2{font-size:clamp(28px,3.6vw,42px);line-height:1.14;margin-block-end:.55em}
h3{font-size:20px;line-height:1.3}
p{margin:0 0 1.15em}
.lede{font-size:clamp(18px,2vw,21px);line-height:1.6;color:var(--ink-soft);max-width:60ch}
.band--ink .lede{color:#C3D2CC}
.prose{max-width:66ch}
.prose p:last-child{margin-block-end:0}

/* ---------- header ---------- */
.top{
  position:sticky;top:0;z-index:60;background:rgba(252,251,248,.94);
  backdrop-filter:blur(8px);border-block-end:1px solid var(--rule);
}
.top__in{display:flex;align-items:center;gap:20px;height:66px}
.mark{font-family:var(--display);font-size:22px;letter-spacing:.06em;text-decoration:none;font-weight:500}
.mark span{color:var(--seal)}
.top__nav{margin-inline-start:auto;display:flex;align-items:center;gap:22px}
.top__nav a{font-size:14px;text-decoration:none;color:var(--ink-soft)}
.top__nav a:hover{color:var(--seal)}
.langs{display:flex;gap:8px;font-family:var(--data);font-size:12px}
.langs a{padding:3px 7px;border:1px solid var(--rule);border-radius:2px;text-decoration:none}
.langs a[aria-current]{background:var(--ink);color:var(--paper);border-color:var(--ink)}
@media(max-width:900px){.top__nav a:not(.btn--wa){display:none}.langs{display:none}}

/* ---------- buttons ---------- */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:9px;
  font-family:var(--body);font-size:16px;font-weight:500;text-decoration:none;
  padding:15px 26px;border-radius:2px;border:1px solid transparent;cursor:pointer;
  transition:background .18s ease,color .18s ease,border-color .18s ease;
}
.btn--solid{background:var(--ink);color:var(--paper)}
.btn--solid:hover{background:var(--seal)}
.btn--line{border-color:var(--ink);color:var(--ink)}
.btn--line:hover{background:var(--ink);color:var(--paper)}
.band--ink .btn--solid{background:var(--paper);color:var(--ink)}
.band--ink .btn--solid:hover{background:var(--seal);color:var(--paper)}
.btn--wa{font-size:14px;padding:9px 16px;background:var(--verified);color:#fff}
.btn--wa:hover{background:var(--ink)}
.btns{display:flex;flex-wrap:wrap;gap:12px;margin-block:28px 14px}
:focus-visible{outline:2.5px solid var(--seal);outline-offset:3px}

/* ---------- hero ---------- */
.hero{padding-block:clamp(48px,7vw,86px) 0}
.hero__grid{display:grid;grid-template-columns:1.15fr .85fr;gap:56px;align-items:start}
@media(max-width:940px){.hero__grid{grid-template-columns:1fr;gap:40px}}
.hero__body{font-size:17px;line-height:1.65;color:var(--ink-soft);max-width:60ch;margin-block-start:1.1em}
.hero__note{font-size:14px;color:var(--muted);max-width:44ch}

/* SIGNATURE — the credential document */
.cred{
  background:#fff;border:1px solid var(--rule);
  box-shadow:0 1px 0 var(--rule),0 18px 44px -32px rgba(18,51,44,.5);
  position:relative;
}
.cred__head{
  padding:16px 22px;border-block-end:1px solid var(--rule);
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  font-family:var(--data);font-size:10.5px;letter-spacing:.17em;text-transform:uppercase;color:var(--muted);
}
.cred__body{padding:24px 22px 22px}
.cred__name{font-family:var(--display);font-size:27px;line-height:1.15;margin-block-end:3px}
.cred__role{font-size:14.5px;color:var(--muted);margin-block-end:20px}
.cred__row{
  display:grid;grid-template-columns:1fr auto;gap:10px;align-items:baseline;
  padding-block:11px;border-block-start:1px dotted var(--rule);
}
.cred__k{font-family:var(--data);font-size:10.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);display:block;margin-block-end:2px}
.cred__v{font-size:15px;line-height:1.35}
.cred__v b{font-family:var(--data);font-weight:500;letter-spacing:.01em}
.cred__verify{
  font-family:var(--data);font-size:11px;letter-spacing:.07em;text-transform:uppercase;
  color:var(--verified);text-decoration:none;white-space:nowrap;border-block-end:1px solid currentColor;padding-block-end:1px;
}
.cred__verify:hover{color:var(--ink)}
.cred__foot{
  padding:14px 22px;background:var(--tone);border-block-start:1px solid var(--rule);
  font-size:13.5px;color:var(--ink-soft);
}
.cred__foot a{color:var(--seal)}
.seal{
  display:inline-flex;align-items:center;gap:6px;color:var(--verified);
  font-family:var(--data);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;
}
.seal svg{width:13px;height:13px}

/* ---------- hero media ---------- */
.hero__media{position:relative}
.hero__img{
  position:relative;aspect-ratio:4/3;border:1px solid var(--rule);border-radius:3px;
  overflow:hidden;background:var(--tone);
}
.hero__img svg{position:absolute;inset:0;width:100%;height:100%}
.hero__cap{
  position:absolute;inset-inline:0;bottom:0;padding:16px 20px;
  font-family:var(--data);font-size:10.5px;line-height:1.5;color:var(--muted);
  background:linear-gradient(to top,rgba(241,239,232,.96) 55%,rgba(241,239,232,0));
}
.hero__cap b{display:block;letter-spacing:.14em;text-transform:uppercase;color:var(--seal);margin-block-end:5px;font-weight:500}
.hero .cred{
  margin-block-start:-64px;margin-inline-start:34px;position:relative;z-index:2;
  border-radius:3px;
}
@media(max-width:940px){
  .hero .cred{margin-block-start:-48px;margin-inline-start:18px;margin-inline-end:18px}
}

/* ---------- disclosure clauses ---------- */
.clauses{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#2C4F46;border:1px solid #2C4F46;margin-block:34px}
.clause{background:var(--ink);padding:26px 24px}
.clause__k{
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;
  color:#8FB3A6;display:block;margin-block-end:12px;
}
.clause p{font-size:15.5px;line-height:1.6;color:#D5E2DD;margin-block-end:0}
@media(max-width:860px){.clauses{grid-template-columns:1fr}}

/* ---------- trust strip ---------- */
.strip{border-block:1px solid var(--rule);background:var(--tone)}
.strip__grid{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--rule)}
.strip__i{background:var(--tone);padding:24px 20px}
.strip__n{font-family:var(--display);font-size:23px;line-height:1.15;margin-block-end:3px}
.strip__d{font-size:13px;color:var(--muted);line-height:1.45}
@media(max-width:1060px){.strip__grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:700px){.strip__grid{grid-template-columns:repeat(2,1fr)}}

/* ---------- steps ---------- */


/* ---------- cost comparison bars ---------- */
.bars{margin-block:34px;border:1px solid var(--rule);background:#fff;padding:30px 32px}
.bars__cap{
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;
  color:var(--muted);margin-block-end:22px;
}
.bar{margin-block-end:22px}
.bar:last-of-type{margin-block-end:0}
.bar__top{display:flex;justify-content:space-between;align-items:baseline;gap:14px;margin-block-end:9px}
.bar__name{font-size:16px}
.bar__val{font-family:var(--data);font-size:13px;color:var(--seal)}
.bar__track{height:12px;background:var(--tone);border:1px solid var(--rule)}
.bar__fill{height:100%;background:var(--ink)}
.bar--you .bar__fill{background:var(--seal)}
.bars__note{margin-block-start:22px;padding-block-start:18px;border-block-start:1px dotted var(--rule);font-size:14px;color:var(--muted)}
.bars__note:last-child{margin-block-end:0}

/* ---------- cost factors ---------- */
.factors{display:grid;grid-template-columns:repeat(5,1fr);gap:1px;background:var(--rule);border:1px solid var(--rule);margin-block:30px}
.factor{background:var(--paper);padding:20px 18px}
.factor__k{font-family:var(--data);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--seal);display:block;margin-block-end:8px}
.factor p{font-size:14px;line-height:1.5;color:var(--ink-soft);margin-block-end:0}
@media(max-width:900px){.factors{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.factors{grid-template-columns:1fr}}

/* ---------- cost ledger ---------- */
.ledger{border:1px solid var(--rule);background:#fff;margin-block-start:30px}
.ledger__head{
  display:flex;justify-content:space-between;padding:13px 22px;border-block-end:1px solid var(--rule);
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);
}
.ledger a{
  position:relative;display:flex;align-items:center;gap:16px;
  padding:14px 22px;text-decoration:none;border-block-end:1px dotted var(--rule);
  transition:background .2s ease;
  animation:tibRise .5s ease var(--d,0ms) both;
}
.ledger.in a{}
.ledger a:last-child{border-block-end:0}
.ledger a::before{
  content:"";position:absolute;inset-block:0;inset-inline-start:0;width:0;
  background:var(--c);transition:width .25s ease;
}
.ledger a:hover{background:color-mix(in srgb,var(--c) 6%,transparent)}
.ledger a:hover::before{width:3px}
.led__ic{
  position:relative;flex:0 0 40px;width:40px;height:40px;border-radius:3px;
  display:grid;place-items:center;overflow:hidden;
}
.led__ic::before{content:"";position:absolute;inset:0;background:var(--c);opacity:.11;transition:opacity .25s ease}
.led__ic svg{position:relative;width:21px;height:21px;stroke:var(--c);fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;transition:stroke .25s ease}
.ledger a:hover .led__ic::before{opacity:1}
.ledger a:hover .led__ic svg{stroke:#fff}
.ledger__proc{font-size:16.5px;flex:1}
.ledger a:hover .ledger__proc{color:var(--c)}
.ledger__go{
  font-family:var(--data);font-size:11px;letter-spacing:.12em;text-transform:uppercase;
  color:var(--muted);white-space:nowrap;transition:color .2s ease,transform .25s ease;
}
.ledger a:hover .ledger__go{color:var(--c);transform:translateX(4px)}
@media(prefers-reduced-motion:reduce){.ledger a:hover .ledger__go{transform:none}}


/* ---------- generic figures ---------- */
.fig{position:relative;background:var(--tone);border:1px solid var(--rule);overflow:hidden}
.fig svg{position:absolute;inset:0;width:100%;height:100%}
.fig__cap{
  position:absolute;inset-inline:0;bottom:0;padding:11px 15px;
  font-family:var(--data);font-size:9.5px;line-height:1.4;color:var(--muted);
  background:linear-gradient(to top,rgba(241,239,232,.96) 55%,rgba(241,239,232,0));
}
.fig--wide{aspect-ratio:16/5;margin-block-start:30px}
.fig--side{aspect-ratio:4/3}
@media(max-width:700px){.fig--wide{aspect-ratio:16/9}}

.splitfig{display:grid;grid-template-columns:.82fr 1.18fr;gap:34px;align-items:start}
@media(max-width:820px){.splitfig{grid-template-columns:1fr;gap:26px}}

/* ---------- network section ---------- */
.netgrid{display:grid;grid-template-columns:1.05fr .95fr;gap:44px;margin-block-start:34px;align-items:start}
@media(max-width:900px){.netgrid{grid-template-columns:1fr;gap:36px}}

.crit{border-block-start:1px solid var(--rule)}
.crit__row{display:grid;grid-template-columns:34px minmax(0,1fr);gap:0 16px;padding-block:18px;border-block-end:1px solid var(--rule)}
.crit__n{font-family:var(--data);font-size:12px;color:var(--seal);padding-block-start:4px}
.crit__t{font-size:16.5px;font-family:var(--display);margin-block-end:5px}
.crit__d{font-size:14.5px;line-height:1.55;color:var(--ink-soft)}

.accred{border:1px solid var(--rule);background:#fff}
.accred__head{
  padding:14px 22px;border-block-end:1px solid var(--rule);
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);
}
.accred__item{padding:22px;border-block-end:1px dotted var(--rule)}
.accred__item:last-child{border-block-end:0}
.accred__mark{font-family:var(--display);font-size:21px;margin-block-end:4px}
.accred__full{font-family:var(--data);font-size:11px;letter-spacing:.06em;color:var(--seal);margin-block-end:10px}
.accred__item p{font-size:14.5px;line-height:1.55;color:var(--ink-soft);margin-block-end:0}

.stories{
  border:1px solid var(--rule);border-inline-start:3px solid var(--seal);background:#fff;
  padding:32px 34px;margin-block-start:56px;
}
.stories h2{font-size:clamp(24px,3vw,32px)}
@media(max-width:600px){.stories{padding:24px 20px}}

/* ---------- running ticker ---------- */
.ticker{background:var(--ink);color:#C3D2CC;overflow:hidden;border-block-end:1px solid #2C4F46}
.ticker__track{display:flex;width:max-content;animation:tick 46s linear infinite}
.ticker__grp{display:flex;flex-shrink:0}
.ticker__i{
  padding:10px 0;margin-inline-end:34px;white-space:nowrap;
  font-family:var(--data);font-size:11.5px;letter-spacing:.11em;text-transform:uppercase;
}
.ticker__i::before{content:"—";color:var(--seal);margin-inline-end:14px}
.ticker:hover .ticker__track{animation-play-state:paused}
@keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- slider ---------- */
.slider{margin-block-start:34px;position:relative}
.slider__vp{overflow:hidden;border:1px solid var(--rule);background:var(--rule)}
.slider__track{display:flex;gap:1px;transition:transform .55s cubic-bezier(.4,0,.2,1)}
.slide{flex:0 0 auto;background:#fff;display:flex;flex-direction:column}
.slide__img{
  position:relative;aspect-ratio:16/10;background:var(--tone);
  border-block-end:1px solid var(--rule);overflow:hidden;
}
.slide__img svg{position:absolute;inset:0;width:100%;height:100%}
.slide__cap{
  position:absolute;inset-inline:0;bottom:0;padding:11px 14px;
  font-family:var(--data);font-size:9.5px;line-height:1.4;color:var(--muted);
  background:linear-gradient(to top,rgba(241,239,232,.96) 55%,rgba(241,239,232,0));
}
.slide__body{padding:24px 24px 26px;display:flex;flex-direction:column;flex:1}
.slide__meta{
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;
  color:var(--seal);display:block;margin-block-end:10px;
}
.slide h3{margin-block-end:9px}
.slide p{font-size:15px;line-height:1.6;color:var(--ink-soft);margin-block-end:.8em}
.slide p:last-of-type{margin-block-end:0}
.slide__note{font-size:13.5px;color:var(--seal);border-inline-start:2px solid var(--seal);padding-inline-start:11px}
.slide__link{margin-block-start:auto;padding-block-start:16px;font-size:15px;font-weight:500;text-decoration:none;align-self:flex-start;border-block-end:1px solid var(--seal)}
.slide__link:hover{color:var(--seal)}

.slider__ctrl{display:flex;align-items:center;gap:14px;margin-block-start:18px}
.slider__arrow{
  width:40px;height:40px;border:1px solid var(--rule);background:transparent;color:var(--ink);
  border-radius:2px;cursor:pointer;font-family:var(--data);font-size:15px;line-height:1;
  transition:background .16s ease,color .16s ease,border-color .16s ease;
}
.slider__arrow:hover:not(:disabled){background:var(--ink);color:var(--paper);border-color:var(--ink)}
.slider__arrow:disabled{opacity:.32;cursor:default}
.slider__dots{display:flex;gap:7px;margin-inline-start:auto}
.slider__dot{width:22px;height:3px;background:var(--rule);border:0;padding:0;cursor:pointer}
.slider__dot[aria-current="true"]{background:var(--seal)}
.band--tone .slider__arrow{border-color:var(--rule)}

@media(prefers-reduced-motion:reduce){
  .ticker__track{animation:none}
  .slider__track{transition:none}
}

/* ---------- animated cost bars ---------- */
.bar__fill{width:0;transition:width 1.3s cubic-bezier(.25,.8,.3,1)}


/* ---------- image slot ---------- */
.slot{
  border:1px dashed var(--rule);background:var(--tone);aspect-ratio:4/3;
  display:flex;flex-direction:column;justify-content:flex-end;padding:18px;
  font-family:var(--data);font-size:11px;line-height:1.5;color:var(--muted);
}
.slot b{display:block;letter-spacing:.14em;text-transform:uppercase;color:var(--seal);margin-block-end:5px;font-weight:500}

/* ---------- faq ---------- */
.faq{margin-block-start:26px;border:1px solid var(--rule);background:#fff}
.faq__item{border-block-end:1px solid var(--rule);position:relative}
.faq__item:last-child{border-block-end:0}
.faq__item::before{
  content:"";position:absolute;inset-block:0;inset-inline-start:0;width:0;
  background:var(--seal);transition:width .28s ease;
}
.faq__item.open::before{width:3px}
.faq__item.open{background:var(--tone)}
.faq__q{
  width:100%;text-align:start;background:none;border:0;cursor:pointer;
  font-family:var(--display);font-size:17.5px;color:var(--ink);line-height:1.35;
  padding:20px 56px 20px 22px;position:relative;transition:color .2s ease;
}
.faq__q:hover{color:var(--seal)}
.faq__item.open .faq__q{color:var(--seal)}
.faq__sign{
  position:absolute;inset-inline-end:20px;top:50%;translate:0 -50%;
  width:20px;height:20px;
}
.faq__sign::before,.faq__sign::after{
  content:"";position:absolute;background:var(--seal);border-radius:1px;
  transition:transform .3s cubic-bezier(.4,0,.2,1),opacity .25s ease;
}
.faq__sign::before{inset-inline:0;top:9px;height:2px}
.faq__sign::after{inset-block:0;left:9px;width:2px}
.faq__item.open .faq__sign::after{transform:rotate(90deg);opacity:0}
.faq__item.open .faq__sign::before{transform:rotate(180deg)}
.faq__a{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.4,0,.2,1)}
.faq__item.open .faq__a{grid-template-rows:1fr}
.faq__a>div{overflow:hidden}
.faq__a p{
  padding:0 56px 22px 22px;margin:0;color:var(--ink-soft);font-size:16px;
  opacity:0;transform:translateY(-6px);transition:opacity .3s ease .08s,transform .3s ease .08s;
}
.faq__item.open .faq__a p{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){
  .faq__a,.faq__a p,.faq__sign::before,.faq__sign::after,.faq__item::before{transition:none}
}

/* ---------- form ---------- */
.form{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-block-start:34px}
.f-full{grid-column:1/-1}
label{display:block;font-family:var(--data);font-size:10.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);margin-block-end:7px}
input,select,textarea{
  width:100%;font-family:var(--body);font-size:16px;color:var(--ink);
  background:#fff;border:1px solid var(--rule);border-radius:2px;padding:13px 14px;
}
textarea{min-height:120px;resize:vertical}
input:focus,select:focus,textarea:focus{border-color:var(--ink);outline-offset:1px}
.file{border:1px dashed var(--rule);background:#fff;padding:20px 16px;text-align:center;font-size:14px;color:var(--muted)}
.form__note{font-size:14px;color:var(--muted);margin-block-start:6px}
@media(max-width:700px){.form{grid-template-columns:1fr}}

/* ---------- footer ---------- */
.foot{background:var(--ink);color:#C3D2CC;padding-block:64px 0;font-size:15px}
.foot__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:36px}
