.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:56px;align-items:start}
.meta{font:10.5px var(--data);letter-spacing:.17em;text-transform:uppercase;color:var(--muted);display:block}
.breadcrumbs{font:12px var(--data);color:var(--muted);letter-spacing:.06em;padding:18px 0 0;max-width:var(--wrap);margin:auto;padding-inline:24px}
.breadcrumbs a{color:var(--muted);text-decoration:none;border-bottom:1px solid transparent}
.breadcrumbs a:hover{color:var(--seal)}
@media(max-width:940px){.hero-grid,.cost-request-grid,.compare-contact-grid,.cost-editorial-grid{grid-template-columns:1fr;gap:34px}}
@media(max-width:700px){.six-quote-grid,.quote-quick-list{grid-template-columns:1fr}}


/* ============ index / cost.json ============ */
.standalone-note{background:var(--ink);color:#c9d6d1;font-size:13.5px;line-height:1.5;padding:11px 24px;border-block-end:1px solid #2c4f46}
.standalone-note a{color:#d8bb86;text-decoration:none;border-bottom:1px solid currentColor}
.hero-copy{min-width:0}
.btn.solid{background:var(--ink);color:var(--paper)}
.btn.solid:hover{background:var(--seal)}
.btn.line{border-color:var(--ink);color:var(--ink)}
.btn.line:hover{background:var(--ink);color:var(--paper)}
.band.tone{background:var(--tone);border-block:1px solid var(--rule)}
.band.ink{background:var(--ink);color:#eef2ef}
.band.ink h2,.band.ink h3{color:#fff}
.band.ink p{color:#c9d6d1}
.band.ink a{color:#d8bb86}
.note{border:1px solid var(--rule);border-inline-start:3px solid var(--seal);background:#fff;border-radius:3px;padding:22px 26px;margin-block-start:26px}
.note p{margin:0;font-size:15.5px;line-height:1.6;color:var(--ink-soft)}
.note strong{color:var(--ink);font-weight:600}
.cost-directory{background:#fff;border:1px solid var(--rule);border-radius:3px;padding:30px;margin-block-start:30px}
.cost-filter-panel{background:var(--tone);border-radius:3px;padding:24px;margin-block-end:0}
.cost-filter-controls{display:flex;flex-wrap:wrap;gap:12px}
.cost-filter-controls .filter-field{flex:1 1 220px}
.cost-department-icon-0{--c:#A03D33}
.cost-department-icon-1{--c:#2E6E6E}
.cost-department-icon-2{--c:#8A6A28}
.cost-department-icon-3{--c:#3D6B8A}
.cost-department-icon-4{--c:#7A4C86}
.cost-department-icon-5{--c:#2F6E52}
.cost-faq{margin-block-start:26px}
.cost-request{padding-block:var(--gap)}
.cost-editorial-grid article,.cost-factor-grid article,.cost-process-grid article,.cost-safety-grid article{
  position:relative;background:#fff;border:1px solid var(--rule);border-radius:3px;padding:24px;box-shadow:0 1px 0 var(--rule)}
.cost-editorial-grid article>span,.cost-factor-grid article>span,.cost-process-grid article>span{
  display:inline-flex;width:26px;height:26px;border-radius:50%;background:var(--tone);color:var(--seal);
  font:500 12px/1 var(--data);align-items:center;justify-content:center;margin-block-end:14px}
.cost-editorial-grid article h3,.cost-factor-grid article h3,.cost-process-grid article h3{font-size:18px;margin-block-end:8px}
.cost-editorial-grid article p,.cost-factor-grid article p,.cost-process-grid article p,.cost-safety-grid article p{font-size:14.5px;line-height:1.6;color:var(--ink-soft);margin:0}
.cost-process-grid article{display:flex;gap:16px;align-items:flex-start}
.cost-process-grid article>span{flex:0 0 26px;margin-block-end:0}
.cost-safety-grid article{border-inline-start:3px solid var(--wc,#A03D33)}
.cost-safety-grid article h3{font-size:17px;margin-block-end:8px;color:var(--ink)}

/* ============ joint-replacement / ptable ============ */
.incl{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-block-start:26px}
.incl__col{background:#fff;border:1px solid var(--rule);border-radius:3px;padding:26px}
.incl__col--out{border-inline-start:3px solid #A03D33}
.incl__k{font:10.5px var(--data);letter-spacing:.15em;text-transform:uppercase;color:var(--seal);display:block;margin-block-end:14px}
.incl__col--out .incl__k{color:#A03D33}
.ask{background:var(--tone);border:1px solid var(--rule);border-radius:3px;padding:28px;margin-block-start:26px}
.ask ol{margin:0;padding-inline-start:22px}
.ask li{margin-block-end:10px;font-size:15px;line-height:1.55;color:var(--ink-soft)}
.ask li:last-child{margin-block-end:0}
@media(max-width:700px){.incl{grid-template-columns:1fr}}

/* ============ what-is-included ============ */
.quote-hero,.compare-hero{padding:clamp(40px,6vw,72px) 0 0}
.quote-hero .hero-grid,.compare-hero .hero-grid{padding-top:22px}
.compare-hero-card{background:#fff;border:1px solid var(--rule);box-shadow:0 1px 0 var(--rule),0 18px 44px -32px rgba(18,51,44,.5);border-radius:3px;padding:26px}
.compare-faq,.compare-contact{margin-block-start:26px}
.compare-contact{background:var(--tone);border:1px solid var(--rule);border-radius:3px;padding:30px}

/* role-based table rows (quote-table / compare-table) */
.quote-table>div[role="row"],.compare-table>div[role="row"]{
  display:grid;grid-template-columns:1fr 1.4fr;gap:14px;align-items:baseline;padding:14px 22px;border-block-end:1px dotted var(--rule)}
.quote-table>div[role="row"]:last-child,.compare-table>div[role="row"]:last-child{border-block-end:0}
.quote-table [role="columnheader"],.compare-table [role="columnheader"]{
  display:block;font:11px var(--data);letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
.quote-table [role="cell"] strong,.compare-table [role="cell"] strong{display:block;font-size:15.5px;font-weight:600}
.quote-table [role="cell"],.compare-table [role="cell"]{font-size:14.5px;color:var(--ink-soft);line-height:1.5}
@media(max-width:700px){.quote-table>div[role="row"],.compare-table>div[role="row"]{grid-template-columns:1fr;gap:4px}}

/* six-quote / quote-warning / payment-check / before-compare */
.six-quote-grid article,.quote-warning-grid article,.payment-check-grid article{
  background:#fff;padding:20px 22px}
.quote-warning-grid article strong{display:block;font-size:16px;margin-block-end:8px;color:var(--ink)}
.six-quote-grid article h3{font-size:16px;margin-block-end:8px}
.six-quote-grid article span,.payment-check-grid article span{
  display:inline-flex;width:24px;height:24px;border-radius:50%;background:var(--tone);color:var(--seal);
  font:500 11px/1 var(--data);align-items:center;justify-content:center;margin-block-end:10px}
.six-quote-grid article p,.quote-warning-grid article p,.payment-check-grid article p{font-size:14px;line-height:1.55;color:var(--ink-soft);margin:0}
.before-compare{border-block:1px solid var(--rule);background:var(--tone);padding-block:var(--gap)}
.before-compare-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;margin-block-start:26px}
.before-compare-grid a{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid var(--rule);border-radius:3px;padding:22px;text-decoration:none;transition:border-color .2s,box-shadow .2s}
.before-compare-grid a:hover{border-color:var(--seal);box-shadow:0 14px 34px -28px rgba(18,51,44,.5)}
.before-compare-icon{flex:0 0 20px;width:20px;height:20px;stroke:var(--seal);fill:none;stroke-width:1.8;margin-block-start:2px;font-family:var(--data);font-size:14px;color:var(--seal)}
.before-compare-grid strong{display:block;font-size:15.5px;font-weight:600;margin-block-end:5px;color:var(--ink)}
.before-compare-grid p{margin:0;font-size:14px;color:var(--muted);line-height:1.5}

/* cost procedure table (joint-replacement) */
.ptable{border:1px solid var(--rule);background:#fff;border-radius:3px;overflow:hidden;margin-block-start:30px}
.ptable table{width:100%;border-collapse:collapse}
.ptable th{background:var(--tone);font:11px var(--data);letter-spacing:.13em;text-transform:uppercase;color:var(--muted);text-align:start;padding:13px 20px}
.ptable td{padding:14px 20px;border-block-start:1px dotted var(--rule);font-size:15px;vertical-align:top}
.ptable .proc-name{font-weight:500;color:var(--ink)}
.ptable .stay{color:var(--muted);white-space:nowrap}
.ptable tbody tr:hover td{background:var(--tone)}
@media(max-width:700px){.ptable td,.ptable th{padding:12px 14px}.ptable .stay{white-space:normal}}
.cost-note{}
